 private static string Id()=>Guid.NewGuid().ToString("N");
 private static async Task<JsonNode> Json(HttpResponseMessage response){using(response){Assert.True(response.IsSuccessStatusCode,$"Unexpected HTTP status {(int)response.StatusCode}.");return JsonNode.Parse(await response.Content.ReadAsStringAsync())!;}}
 private async Task<(HttpClient Client,string Owner)> Customer(){await using var scope=sql.Factory.Services.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var name="realtime"+Id();var user=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true};Assert.True((await users.CreateAsync(user,sql.Password)).Succeeded);var signed=await scope.ServiceProvider.GetRequiredService<AuthService>().PasswordAsync(new(name,sql.Password),true,true,false,default);var client=sql.Factory.CreateClient(new(){HandleCookies=false});client.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3000");client.DefaultRequestHeaders.Authorization=new("Bearer",signed.AccessToken);return(client,user.Id);}
 private async Task<HttpClient> Staff(){await using var scope=sql.Factory.Services.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var name="livestaff"+Id();var user=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true,RequireMfa=true};Assert.True((await users.CreateAsync(user,sql.Password)).Succeeded);Assert.True((await users.AddToRoleAsync(user,"SupportAgent")).Succeeded);var c=sql.Factory.CreateClient(new(){HandleCookies=false});c.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3173");c.DefaultRequestHeaders.Add("X-Sayman-Client","admin");c.DefaultRequestHeaders.Add("X-Sayman-Admin","1");var pending=await Json(await c.PostAsJsonAsync("/api/auth/password",new{Identifier=name,Password=sql.Password}));c.DefaultRequestHeaders.Authorization=new("Bearer",pending["accessToken"]!.GetValue<string>());using(var denied=await c.PostAsync("/api/admin/realtime/negotiate?negotiateVersion=1",new StringContent("")))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);var setup=await Json(await c.PostAsJsonAsync("/api/auth/mfa/setup",new{}));c.DefaultRequestHeaders.Authorization=new("Bearer",setup["accessToken"]!.GetValue<string>());var signed=await Json(await c.PostAsJsonAsync("/api/auth/mfa/verify",new{Code=Totp.Code(setup["secret"]!.GetValue<string>(),DateTimeOffset.UtcNow.ToUnixTimeSeconds()/30)}));c.DefaultRequestHeaders.Authorization=new("Bearer",signed["accessToken"]!.GetValue<string>());return c;}
 private static async Task<JsonNode> Create(HttpClient customer)=>await Json(await customer.PostAsJsonAsync("/api/support/tickets/commands/"+Id(),new CreateTicketInput("تیکت نمونهٔ زنده","این متن فقط در SQL موقت است.","fa")));
 private sealed class PollConnection(HttpClient client,string root,string token):IAsyncDisposable
 {
  private int sequence;
  private string Url=>root+"?id="+Uri.EscapeDataString(token);
  public async Task<HttpStatusCode> TryWith(HttpClient other,string? otherRoot=null){using var response=await other.GetAsync((otherRoot??root)+"?id="+Uri.EscapeDataString(token));return response.StatusCode;}
  public async Task<string[]> Wait(string[] expected,CancellationToken ct,string? capture=null){var scopes=new List<string>();while(expected.Except(scopes,StringComparer.Ordinal).Any()){using var response=await client.GetAsync(Url,HttpCompletionOption.ResponseHeadersRead,ct);Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Contains("no-store",response.Headers.CacheControl!.ToString());var raw=await response.Content.ReadAsStringAsync(ct);foreach(var frame in raw.Split('\u001e',StringSplitOptions.RemoveEmptyEntries)){var value=JsonNode.Parse(frame)!;if(value["type"]?.GetValue<int>()!=1)continue;Assert.Equal("Changed",value["target"]!.GetValue<string>());var args=value["arguments"]!.AsArray();Assert.Single(args);var pulse=args[0]!.AsObject();Assert.Equal(new[]{"schemaVersion","scope"},pulse.Select(x=>x.Key).Order(StringComparer.Ordinal));Assert.Equal(1,pulse["schemaVersion"]!.GetValue<int>());var scope=pulse["scope"]!.GetValue<string>();Assert.Contains(scope,new[]{"support","notifications"});scopes.Add(scope);}
    if(capture is not null&&raw.Length>0&&Environment.GetEnvironmentVariable("SHOP_REALTIME_WIRE_DIR")is{Length:>0}dir){Directory.CreateDirectory(dir);var name=capture+"-"+(++sequence);await File.WriteAllTextAsync(Path.Combine(dir,name+".frame.txt"),raw);await File.WriteAllTextAsync(Path.Combine(dir,name+".meta.json"),System.Text.Json.JsonSerializer.Serialize(new{actualSqlSignalRResponse=true,syntheticQaOnly=true,status=200,path=root+"?id=[private]",queryTokenNeverPersisted=true,rawEventFrames=true}));}
   }return scopes.ToArray();}
  public async Task NoChange(){using var stop=new CancellationTokenSource(TimeSpan.FromMilliseconds(800));try{while(true){using var response=await client.GetAsync(Url,HttpCompletionOption.ResponseHeadersRead,stop.Token);Assert.Equal(HttpStatusCode.OK,response.StatusCode);var raw=await response.Content.ReadAsStringAsync(stop.Token);foreach(var frame in raw.Split('\u001e',StringSplitOptions.RemoveEmptyEntries)){var value=JsonNode.Parse(frame)!;Assert.False(value["type"]?.GetValue<int>()==1,"An unrelated connection received a change pulse.");}}}catch(OperationCanceledException)when(stop.IsCancellationRequested){}catch(HttpRequestException)when(stop.IsCancellationRequested){}}
  public async ValueTask DisposeAsync(){try{using var response=await client.DeleteAsync(Url);}catch(Exception error)when(error is HttpRequestException or OperationCanceledException){}}
  public static async Task<PollConnection> Start(HttpClient client,string root){var negotiation=await Json(await client.PostAsync(root+"/negotiate?negotiateVersion=1",new StringContent("")));Assert.Equal(1,negotiation["negotiateVersion"]!.GetValue<int>());Assert.Single(negotiation["availableTransports"]!.AsArray());Assert.Equal("LongPolling",negotiation["availableTransports"]![0]!["transport"]!.GetValue<string>());var token=negotiation["connectionToken"]!.GetValue<string>();Assert.InRange(token.Length,100,4096);var connection=new PollConnection(client,root,token);using(var first=await client.GetAsync(connection.Url)){Assert.Equal(HttpStatusCode.OK,first.StatusCode);Assert.Equal("",await first.Content.ReadAsStringAsync());}using(var handshake=await client.PostAsync(connection.Url,new StringContent("{\"protocol\":\"json\",\"version\":1}\u001e",Encoding.UTF8,"text/plain")))Assert.Equal(HttpStatusCode.OK,handshake.StatusCode);using var ready=new CancellationTokenSource(TimeSpan.FromSeconds(5));await connection.Wait(root.StartsWith("/api/admin/",StringComparison.Ordinal)?["support"]:["support","notifications"],ready.Token);return connection;}
 }
 [Fact]public async Task ActualSignalRDeliversOnlyCommittedPrivateOwnerAndAuthorizedStaffPulses()
 {
  var person=await Customer();using var customer=person.Client;var otherPerson=await Customer();using var other=otherPerson.Client;using var staff=await Staff();var created=await Create(customer);var id=created["ticket"]!["id"]!.GetValue<string>();await using var own=await PollConnection.Start(customer,"/api/realtime");await using var foreign=await PollConnection.Start(other,"/api/realtime");await using var agent=await PollConnection.Start(staff,"/api/admin/realtime");using var deadline=new CancellationTokenSource(TimeSpan.FromSeconds(6));var ownerPulse=own.Wait(["support","notifications"],deadline.Token,"owner-reply");var staffPulse=agent.Wait(["support"],deadline.Token,"staff-reply");var otherQuiet=foreign.NoChange();var command=Id();var path=$"/api/admin/support/tickets/{id}/replies/{command}";var input=new ReplyTicketInput(created["ticket"]!["version"]!.GetValue<string>(),"پاسخ زندهٔ نمونهٔ SQL","fa");await Json(await staff.PostAsJsonAsync(path,input));await ownerPulse;await staffPulse;await otherQuiet;var messages=await Json(await customer.GetAsync($"/api/support/tickets/{id}/messages"));Assert.Equal(2,messages["items"]!.AsArray().Count);await Json(await staff.PostAsJsonAsync(path,input));await own.NoChange();await agent.NoChange();
 }
 [Fact]public async Task ConnectionEnvelopeCannotBeReusedByOtherAccountsOrAudienceAndStampRevocationIsRechecked()
 {
  var person=await Customer();using var customer=person.Client;var otherPerson=await Customer();using var other=otherPerson.Client;using var staff=await Staff();await using var own=await PollConnection.Start(customer,"/api/realtime");Assert.Equal(HttpStatusCode.Forbidden,await own.TryWith(other));Assert.Equal(HttpStatusCode.Forbidden,await own.TryWith(staff,"/api/admin/realtime"));await using var supportConnection=await PollConnection.Start(staff,"/api/admin/realtime");Assert.Equal(HttpStatusCode.Forbidden,await supportConnection.TryWith(staff,"/api/realtime"));
  await using(var scope=sql.Factory.Services.CreateAsyncScope()){var user=await scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>().FindByIdAsync(person.Owner);var signed=await scope.ServiceProvider.GetRequiredService<AuthService>().PasswordAsync(new(user!.UserName!,sql.Password),true,true,false,default);using var changedToken=sql.Factory.CreateClient(new(){HandleCookies=false});changedToken.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3000");changedToken.DefaultRequestHeaders.Authorization=new("Bearer",signed.AccessToken);Assert.Equal(HttpStatusCode.Forbidden,await own.TryWith(changedToken));}
  await using(var scope=sql.Factory.Services.CreateAsyncScope()){var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var user=await users.FindByIdAsync(person.Owner);Assert.True((await users.UpdateSecurityStampAsync(user!)).Succeeded);}Assert.Equal(HttpStatusCode.Unauthorized,await own.TryWith(customer));using(var invalid=await other.GetAsync("/api/realtime?id="+new string('a',64)+"&access_token=synthetic-not-a-token"))Assert.Equal(HttpStatusCode.BadRequest,invalid.StatusCode);using(var invalid=await other.PostAsync("/api/realtime/negotiate?negotiateVersion=1",new StringContent("{}")))Assert.Equal(HttpStatusCode.BadRequest,invalid.StatusCode);
 }
 private sealed class CaptureDispatcher(bool fail=false):IPrivateRealtimeDispatcher{public List<PrivateRealtimeDelivery> Values=[];public Task DispatchAsync(PrivateRealtimeDelivery[] values,CancellationToken ct){Values.AddRange(values);if(fail)throw new InvalidOperationException("Synthetic transport-only failure.");return Task.CompletedTask;}}
 private HttpClient WithDispatcher(HttpClient original,IPrivateRealtimeDispatcher dispatcher,out WebApplicationFactory<Program> factory){factory=sql.Factory.WithWebHostBuilder(builder=>builder.ConfigureTestServices(services=>{services.RemoveAll<IPrivateRealtimeDispatcher>();services.AddSingleton(dispatcher);}));var client=factory.CreateClient(new(){HandleCookies=false});client.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3173");client.DefaultRequestHeaders.Add("X-Sayman-Client","admin");client.DefaultRequestHeaders.Authorization=original.DefaultRequestHeaders.Authorization;return client;}
 [Fact]public async Task AuditRollbackAndReceiptReplayDispatchNothingAndTransportFailureCannotUndoSqlCommit()
 {
  var person=await Customer();using var customer=person.Client;using var staff=await Staff();var created=await Create(customer);var id=created["ticket"]!["id"]!.GetValue<string>();var input=new ReplyTicketInput(created["ticket"]!["version"]!.GetValue<string>(),"Committed SQL survives a realtime transport failure.","en");var path=$"/api/admin/support/tickets/{id}/replies/{Id()}";var capture=new CaptureDispatcher();using var observing=WithDispatcher(staff,capture,out var factory);using(factory){await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<Shop.Modules.Identity.IdentityDbContext>();Assert.StartsWith("SaymanTest_",db.Database.GetDbConnection().Database);await db.Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_RealtimeAuditFailure CHECK ([Resource] NOT LIKE '/api/admin/support/tickets/%/replies/%')");}
   try{using var failed=await observing.PostAsJsonAsync(path,input);Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<Shop.Modules.Identity.IdentityDbContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_RealtimeAuditFailure");}Assert.Empty(capture.Values);await Json(await observing.PostAsJsonAsync(path,input));Assert.Equal(3,capture.Values.Count);await Json(await observing.PostAsJsonAsync(path,input));Assert.Equal(3,capture.Values.Count);}
  created=await Create(customer);id=created["ticket"]!["id"]!.GetValue<string>();var failedDispatcher=new CaptureDispatcher(true);using var failing=WithDispatcher(staff,failedDispatcher,out var failFactory);using(failFactory){await Json(await failing.PostAsJsonAsync($"/api/admin/support/tickets/{id}/replies/{Id()}",input with{Version=created["ticket"]!["version"]!.GetValue<string>()}));Assert.Equal(3,failedDispatcher.Values.Count);var messages=await Json(await customer.GetAsync($"/api/support/tickets/{id}/messages"));Assert.Equal(2,messages["items"]!.AsArray().Count);await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.Single(await scope.ServiceProvider.GetRequiredService<NotificationsDbContext>().Inbox.Where(x=>x.TicketId==id).ToArrayAsync());}
 }
}
